/* **************************************** */
// Owner
/* **************************************** */
// Columns:
// locations_xs: float
// locations_ys: float
// locations_zs: float
// rotations_pitches: float
// rotations_yaws: float
// rotations_rolls: float
// base_velocities_xs: float
// base_velocities_ys: float
// base_velocities_zs: float
// damages: std::int32_t
// speeds: float
// max_distances: float
// instigator_ids: EntityId
// sources: ioj::sim::LaserSource
struct LaserSpawnRequests
    : protected ioj::native_soa::StorageState
    , ioj::native_soa::StorageOperations {
    using soa_schema = LaserSpawnRequestsSchema;
    using Operations = ioj::native_soa::StorageOperations;
    using Layout = LaserSpawnRequestsLayout;
    using size_type = Layout::size_type;
    using byte_size_type = Layout::byte_size_type;

    static constexpr auto capacity_granularity = Layout::capacity_granularity;
    static constexpr auto allocation_alignment = Layout::allocation_alignment;
    static constexpr auto capacity_block_bound = Layout::capacity_block_bound;
    static constexpr auto max_capacity = Layout::max_capacity;

    static constexpr auto layout_bytes(byte_size_type blocks) noexcept -> byte_size_type {
        return Layout::layout_bytes(blocks);
    }

    using View = LaserSpawnRequestsView;
    using ConstView = LaserSpawnRequestsConstView;

    /* **************************************** */
    // Lifetime
    /* **************************************** */
    LaserSpawnRequests() noexcept
        : LaserSpawnRequests{*std::pmr::get_default_resource()} {}
    explicit LaserSpawnRequests(std::pmr::memory_resource& resource) noexcept
        : resource_{&resource} {}
    auto get_memory_resource() const noexcept -> std::pmr::memory_resource* { return resource_; }
    ~LaserSpawnRequests() { Operations::release_storage(*this); }
    LaserSpawnRequests(LaserSpawnRequests const&) = delete;
    auto operator=(LaserSpawnRequests const&) -> LaserSpawnRequests& = delete;
    LaserSpawnRequests(LaserSpawnRequests&& other) noexcept
        : resource_{other.resource_} {
        Operations::take_storage(*this, other);
    }
    auto operator=(LaserSpawnRequests&& other) -> LaserSpawnRequests& {
        return Operations::move_assign(*this, other);
    }
  protected:
    template <typename Byte>
    struct DataPointers {
        template <typename T>
        using Element = std::conditional_t<std::is_const_v<Byte>, T const, T>;
        Element<float>* locations_xs{};
        Element<float>* locations_ys{};
        Element<float>* locations_zs{};
        Element<float>* rotations_pitches{};
        Element<float>* rotations_yaws{};
        Element<float>* rotations_rolls{};
        Element<float>* base_velocities_xs{};
        Element<float>* base_velocities_ys{};
        Element<float>* base_velocities_zs{};
        Element<std::int32_t>* damages{};
        Element<float>* speeds{};
        Element<float>* max_distances{};
        Element<EntityId>* instigator_ids{};
        Element<LaserSource>* sources{};
        auto operator+(size_type const offset) const noexcept -> DataPointers {
            if (locations_xs == nullptr) {
                return {};
            }
            return {locations_xs + offset,
                    locations_ys + offset,
                    locations_zs + offset,
                    rotations_pitches + offset,
                    rotations_yaws + offset,
                    rotations_rolls + offset,
                    base_velocities_xs + offset,
                    base_velocities_ys + offset,
                    base_velocities_zs + offset,
                    damages + offset,
                    speeds + offset,
                    max_distances + offset,
                    instigator_ids + offset,
                    sources + offset};
        }
    };
  private:
    friend Operations;
    friend ::ioj::soa_storage_detail::StorageRequirements;
    /* **************************************** */
    // Column pointers
    /* **************************************** */
    template <typename Byte>
    static auto make_data_unchecked(Byte* const data, byte_size_type const blocks) noexcept
        -> DataPointers<Byte> {
        ioj::native_soa::LayoutCursor cursor{blocks};
        return {cursor.column_pointer(data, Layout::columns.Locations.XsColumn),
                cursor.column_pointer(data, Layout::columns.Locations.YsColumn),
                cursor.column_pointer(data, Layout::columns.Locations.ZsColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.PitchesColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.YawsColumn),
                cursor.column_pointer(data, Layout::columns.Rotations.RollsColumn),
                cursor.column_pointer(data, Layout::columns.BaseVelocities.XsColumn),
                cursor.column_pointer(data, Layout::columns.BaseVelocities.YsColumn),
                cursor.column_pointer(data, Layout::columns.BaseVelocities.ZsColumn),
                cursor.column_pointer(data, Layout::columns.DamagesColumn),
                cursor.column_pointer(data, Layout::columns.SpeedsColumn),
                cursor.column_pointer(data, Layout::columns.MaxDistancesColumn),
                cursor.column_pointer(data, Layout::columns.InstigatorIdsColumn),
                cursor.column_pointer(data, Layout::columns.SourcesColumn)};
    }

    /* **************************************** */
    // Typed mutations and growth
    /* **************************************** */
    void default_construct_columns(size_type const first, size_type const count) {
        using ioj::native_soa::default_construct_n;
        auto const columns{make_data_unchecked(data_, capacity_blocks()) + first};
        default_construct_n(columns.locations_xs, count);
        default_construct_n(columns.locations_ys, count);
        default_construct_n(columns.locations_zs, count);
        default_construct_n(columns.rotations_pitches, count);
        default_construct_n(columns.rotations_yaws, count);
        default_construct_n(columns.rotations_rolls, count);
        default_construct_n(columns.base_velocities_xs, count);
        default_construct_n(columns.base_velocities_ys, count);
        default_construct_n(columns.base_velocities_zs, count);
        default_construct_n(columns.damages, count);
        default_construct_n(columns.speeds, count);
        default_construct_n(columns.max_distances, count);
        default_construct_n(columns.instigator_ids, count);
        default_construct_n(columns.sources, count);
    }
    template <bool Overlapping, typename Byte>
    static void transfer_columns(DataPointers<std::byte> const& destination,
                                 DataPointers<Byte> const& source,
                                 size_type count) {
        auto transfer = [count](auto* dst, auto const* src) {
            ioj::native_soa::transfer_n<Overlapping>(dst, src, count);
        };
        transfer(destination.locations_xs, source.locations_xs);
        transfer(destination.locations_ys, source.locations_ys);
        transfer(destination.locations_zs, source.locations_zs);
        transfer(destination.rotations_pitches, source.rotations_pitches);
        transfer(destination.rotations_yaws, source.rotations_yaws);
        transfer(destination.rotations_rolls, source.rotations_rolls);
        transfer(destination.base_velocities_xs, source.base_velocities_xs);
        transfer(destination.base_velocities_ys, source.base_velocities_ys);
        transfer(destination.base_velocities_zs, source.base_velocities_zs);
        transfer(destination.damages, source.damages);
        transfer(destination.speeds, source.speeds);
        transfer(destination.max_distances, source.max_distances);
        transfer(destination.instigator_ids, source.instigator_ids);
        transfer(destination.sources, source.sources);
    }
    template <typename Columns>
    static auto source_pointers(Columns const& source) -> DataPointers<std::byte const>
        requires ioj::soa_storage_detail::SoaSourceFor<Columns, LaserSpawnRequests, size_type>
    {
        using ioj::native_soa::source_data;
        auto const& locations_view{source.view_locations()};
        auto const& rotations_view{source.view_rotations()};
        auto const& base_velocities_view{source.view_base_velocities()};
        return {source_data(locations_view.xs()),
                source_data(locations_view.ys()),
                source_data(locations_view.zs()),
                source_data(rotations_view.pitches()),
                source_data(rotations_view.yaws()),
                source_data(rotations_view.rolls()),
                source_data(base_velocities_view.xs()),
                source_data(base_velocities_view.ys()),
                source_data(base_velocities_view.zs()),
                source_data(source.damages()),
                source_data(source.speeds()),
                source_data(source.max_distances()),
                source_data(source.instigator_ids()),
                source_data(source.sources())};
    }
  public:
    auto view_locations(this auto& self) { return self.get_view().view_locations(); }
    auto view_rotations(this auto& self) { return self.get_view().view_rotations(); }
    auto view_base_velocities(this auto& self) { return self.get_view().view_base_velocities(); }
    auto damages(this auto& self) { return self.get_view().damages(); }
    auto speeds(this auto& self) { return self.get_view().speeds(); }
    auto max_distances(this auto& self) { return self.get_view().max_distances(); }
    auto instigator_ids(this auto& self) { return self.get_view().instigator_ids(); }
    auto sources(this auto& self) { return self.get_view().sources(); }
    void set(size_type index,
             float const new_locations_xs,
             float const new_locations_ys,
             float const new_locations_zs,
             float const new_rotations_pitches,
             float const new_rotations_yaws,
             float const new_rotations_rolls,
             float const new_base_velocities_xs,
             float const new_base_velocities_ys,
             float const new_base_velocities_zs,
             std::int32_t const new_damages,
             float const new_speeds,
             float const new_max_distances,
             EntityId const new_instigator_ids,
             LaserSource const new_sources) {
        assert(index < num());
        get_view().view_locations().xs()[index] = new_locations_xs;
        get_view().view_locations().ys()[index] = new_locations_ys;
        get_view().view_locations().zs()[index] = new_locations_zs;
        get_view().view_rotations().pitches()[index] = new_rotations_pitches;
        get_view().view_rotations().yaws()[index] = new_rotations_yaws;
        get_view().view_rotations().rolls()[index] = new_rotations_rolls;
        get_view().view_base_velocities().xs()[index] = new_base_velocities_xs;
        get_view().view_base_velocities().ys()[index] = new_base_velocities_ys;
        get_view().view_base_velocities().zs()[index] = new_base_velocities_zs;
        get_view().damages()[index] = new_damages;
        get_view().speeds()[index] = new_speeds;
        get_view().max_distances()[index] = new_max_distances;
        get_view().instigator_ids()[index] = new_instigator_ids;
        get_view().sources()[index] = new_sources;
    }
    size_type add(float const new_locations_xs,
                  float const new_locations_ys,
                  float const new_locations_zs,
                  float const new_rotations_pitches,
                  float const new_rotations_yaws,
                  float const new_rotations_rolls,
                  float const new_base_velocities_xs,
                  float const new_base_velocities_ys,
                  float const new_base_velocities_zs,
                  std::int32_t const new_damages,
                  float const new_speeds,
                  float const new_max_distances,
                  EntityId const new_instigator_ids,
                  LaserSource const new_sources) {
        auto const index{num()};
        add_uninitialised(1);
        set(index,
            new_locations_xs,
            new_locations_ys,
            new_locations_zs,
            new_rotations_pitches,
            new_rotations_yaws,
            new_rotations_rolls,
            new_base_velocities_xs,
            new_base_velocities_ys,
            new_base_velocities_zs,
            new_damages,
            new_speeds,
            new_max_distances,
            new_instigator_ids,
            new_sources);
        return index;
    }
    void set(size_type index,
             Vector3f const new_locations,
             Rotator3f const new_rotations,
             Vector3f const new_base_velocities,
             std::int32_t const new_damages,
             float const new_speeds,
             float const new_max_distances,
             EntityId const new_instigator_ids,
             LaserSource const new_sources) {
        assert(index < num());
        get_view().view_locations().set(index, new_locations);
        get_view().view_rotations().set(index, new_rotations);
        get_view().view_base_velocities().set(index, new_base_velocities);
        get_view().damages()[index] = new_damages;
        get_view().speeds()[index] = new_speeds;
        get_view().max_distances()[index] = new_max_distances;
        get_view().instigator_ids()[index] = new_instigator_ids;
        get_view().sources()[index] = new_sources;
    }
    size_type add(Vector3f const new_locations,
                  Rotator3f const new_rotations,
                  Vector3f const new_base_velocities,
                  std::int32_t const new_damages,
                  float const new_speeds,
                  float const new_max_distances,
                  EntityId const new_instigator_ids,
                  LaserSource const new_sources) {
        auto const index{num()};
        add_uninitialised(1);
        set(index,
            new_locations,
            new_rotations,
            new_base_velocities,
            new_damages,
            new_speeds,
            new_max_distances,
            new_instigator_ids,
            new_sources);
        return index;
    }
    void apply_permutation(std::span<size_type> indices) {
        assert(indices.size() == num_);
        auto const columns{get_data()};
        auto const permute{ioj::ColumnPermutation{num_, indices}};
        permute(columns.locations_xs,
                columns.locations_ys,
                columns.locations_zs,
                columns.rotations_pitches,
                columns.rotations_yaws,
                columns.rotations_rolls,
                columns.base_velocities_xs,
                columns.base_velocities_ys,
                columns.base_velocities_zs,
                columns.damages,
                columns.speeds,
                columns.max_distances,
                columns.instigator_ids,
                columns.sources);
    }
  private:
    std::pmr::memory_resource* resource_{};
};
